import{_ as a,o as e,c as n,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"SSH 配置","description":"","frontmatter":{},"headers":[],"relativePath":"system-config/ssh.md","filePath":"system-config/ssh.md","lastUpdated":1791990988000}'),p={name:"system-config/ssh.md"};function o(i,s,c,l,d,h){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="ssh-配置" tabindex="-1">SSH 配置 <a class="header-anchor" href="#ssh-配置" aria-label="Permalink to &quot;SSH 配置&quot;">​</a></h1><h2 id="生成密钥" tabindex="-1">生成密钥 <a class="header-anchor" href="#生成密钥" aria-label="Permalink to &quot;生成密钥&quot;">​</a></h2><p>生成一个 ed25519 密钥，放入 <code>.ssh</code> 文件夹中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh-keygen -t ed25519</span></span></code></pre></div><p>把生成的公钥写入服务器的验证公钥文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat ~/.ssh/id_ed25519.pub &gt; ~/.ssh/authorized_keys</span></span>
<span class="line"><span>chmod 700 ~/.ssh</span></span>
<span class="line"><span>chmod 600 ~/.ssh/authorized_keys</span></span></code></pre></div><blockquote><p>密钥权限必须是 <code>~/.ssh</code> 为 700、<code>authorized_keys</code> 为 600，否则 SSH 会因权限过宽而拒绝使用。</p></blockquote><h2 id="修改-ssh-配置" tabindex="-1">修改 SSH 配置 <a class="header-anchor" href="#修改-ssh-配置" aria-label="Permalink to &quot;修改 SSH 配置&quot;">​</a></h2><p>编辑 <code>/etc/ssh/sshd_config</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 密码登录</span></span>
<span class="line"><span>PasswordAuthentication no    # 是否允许密码验证</span></span>
<span class="line"><span>PermitRootLogin yes          # 是否允许 root 直接登录</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 密钥登录</span></span>
<span class="line"><span>RSAAuthentication yes        # 启用 RSA 认证，默认为 yes</span></span>
<span class="line"><span>PubkeyAuthentication yes     # 启用公钥认证，默认为 yes</span></span></code></pre></div><blockquote><p><code>PasswordAuthentication no</code> 会关闭密码登录，改之前务必确认密钥已经配好、能正常登录，否则可能把自己锁在门外。</p></blockquote><p>改完重启 SSH 服务生效：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl restart ssh</span></span></code></pre></div>`,13)])])}const b=a(p,[["render",o]]);export{u as __pageData,b as default};
